// @ts-strict
// Worker of «Export all my data» (esporta-dati.js): packs the files into one stored ZIP with the Rust writer of mzlab-wasm (zip_len / zip_write).
// Separate from the worker of the engine so the export works with or without open files.
// @ts-ignore the engine is generated by wasm-bindgen: it is not in the tree
import init, { zip_len, zip_write } from "./wasm/mzlab_wasm.js";

const ready = init();

onmessage = async ev => {
  const m = ev.data;
  try {
    await ready;
    const packed = new Uint8Array(m.packed);
    const out = new Uint8Array(zip_len(packed));
    zip_write(packed, out);
    postMessage({ id: m.id, zip: out.buffer }, [out.buffer]);
  } catch (e) {
    postMessage({ id: m.id, error: String(e) });
  }
};
